import { ratel } from "@ratel-ai/sdk";
import * as ratelCloud from "@ratel-ai/cloud-sdk/runtime";

const runtime = ratel();
ratelCloud.attach(runtime, { useCloudDefinitions: true }); // Reads RATEL_API_KEY.

await runtime.tools.register({
  id: "weather.lookup",
  name: "weather.lookup",
  description: "Fetch a forecast for one city.",
  inputSchema: {
    type: "object",
    properties: { city: { type: "string" } },
    required: ["city"],
  },
  outputSchema: { type: "object" },
  execute: async ({ city }) => getForecast(city),
});

