import { NodeSDK } from "@opentelemetry/sdk-node";
import { RatelSpanProcessor } from "@ratel-ai/cloud-sdk/otel";

const sdk = new NodeSDK({
  serviceName: "site-copilot",
  spanProcessors: [
    // Reads RATEL_API_KEY. Forwards gen_ai.* / ratel.* spans to
    // Ratel; any exporter you already run is left untouched.
    new RatelSpanProcessor({
      endpoint: "https://ratel.example.com/v1/traces",
    }),
  ],
});

sdk.start();

import { NodeSDK } from "@opentelemetry/sdk-node";
import { RatelSpanProcessor } from "@ratel-ai/cloud-sdk/otel";

// Content capture (opt-in): search queries and tool arguments ride
// along on the spans. Delete these lines to send runtime events only.
process.env.OTEL_INSTRUMENTATION_GENAI_CAPTURE_MESSAGE_CONTENT =
  "SPAN_AND_EVENT";

const sdk = new NodeSDK({
  serviceName: "site-copilot",
