    // Reads RATEL_API_KEY. Forwards gen_ai.* / ratel.* spans to
    // Ratel; any exporter you already run is left untouched.
    new RatelSpanProcessor({
      endpoint: "https://ratel.example.com/v1/traces",
    }),
  ],
});

sdk.start();
